#include <bits/stdc++.h>
using namespace std;

double p, memo[2020][2020];
int n, t;

double dp(int pos, int tm) {
    if (pos == n + 1 || tm == 0) return pos - 1;

    double &result = memo[pos][tm];
    if (result >= 0.0) return result;

    return result = p * dp(pos + 1, tm - 1)
                  + (1.0 - p) * dp(pos, tm - 1);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> p >> t;
    fill(&memo[0][0], &memo[0][0] + 2020 * 2020, -1.0);

    cout << fixed << setprecision(10) << dp(1, t) << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

double p, go[2020][2020];
int t, n;

double dp(int pos, int tm) {
    if (pos == n + 1 || tm == 0) {
        return pos - 1;
    }

    if (go[pos][tm] > -0.5) {
        return go[pos][tm];
    }

    return go[pos][tm] =
        dp(pos + 1, tm - 1) * p +
        dp(pos, tm - 1) * (1.0 - p);
}

